  // exhaust stacks
  ctx.fillStyle = '#51433b';
  roundRect(ctx, -13, -8.6, 3.2, 5, 0.8);
  ctx.fill();
  roundRect(ctx, -13, 3.6, 3.2, 5, 0.8);
  ctx.fill();
  ctx.fillStyle = 'rgba(255, 136, 52, 0.55)';
  ctx.beginPath();
  ctx.arc(-11.4, -9.4, 1.4, 0, TAU);
  ctx.arc(-11.4, 9.4, 1.4, 0, TAU);
